const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let state=null,page=location.hash.slice(1)||'dashboard',query='',severityFilter='all',statusFilter='all',toastTimer;
const labelMap={dashboard:'Dashboard',targets:'Targets',scans:'Network scans',assets:'Assets',findings:'Vulnerabilities',graph:'Security graph',risk:'Risk analysis',packets:'Packet analysis',logs:'Log analysis',remediation:'Remediation',reports:'Reports',settings:'Settings'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=x=>x?new Date(x).toLocaleString([],{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—';
const asset=id=>state?.assets.find(a=>a.id===id);
const toast=(s,error=false)=>{const t=$('#toast');t.textContent=s;t.classList.toggle('error',error);t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3300)};
async function api(url,options={}){let r;try{r=await fetch(url,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}})}catch{return Promise.reject(new Error('Could not reach the local CampusShield server.'))}const ct=r.headers.get('content-type')||'';const d=ct.includes('json')?await r.json():await r.blob();if(!r.ok)throw new Error(d?.error||'Request failed');return d}
const post=(url,data)=>api(url,{method:'POST',body:JSON.stringify(data)}),patch=(url,data)=>api(url,{method:'PATCH',body:JSON.stringify(data)}),del=url=>api(url,{method:'DELETE'});
const setPage=p=>{page=labelMap[p]?p:'dashboard';location.hash=page;render()};
function pageHead(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">CampusShield / ${esc(title)}</div><h1>${esc(title)}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function btn(text,onclick,primary=false,sm=false,icon=''){return `<button class="btn ${primary?'btn-primary':''} ${sm?'btn-sm':''}" data-action="${esc(onclick)}">${icon?`<span>${icon}</span>`:''}${text}</button>`}
function riskPill(x){return `<span class="risk-pill ${esc(x)}">${esc(x)}</span>`}function sevPill(x){return `<span class="severity-pill ${esc(x)}">${esc(x)}</span>`}function statusPill(x){return `<span class="status-pill ${esc(x)}">${esc(String(x).replace('_',' '))}</span>`}
function empty(title,desc,cta=''){return `<div class="empty-state"><div class="empty-symbol">◈</div><b>${title}</b><p>${desc}</p>${cta}</div>`}
function render(){if(!state)return;$('#pageCrumb').textContent=labelMap[page]||'Dashboard';$$('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#modeChip').innerHTML=`<span class="pulse-dot"></span>${state.mode==='demo'?'DEMO MODE':'LIVE LAB MODE'}`;$('#findingBadge').textContent=state.findings.filter(f=>f.status!=='fixed').length;const view=$('#view');const renderers={dashboard:dashboard,targets:targets,scans:scans,assets:assetsPage,findings:findingsPage,graph:graphPage,risk:riskPage,packets:packetsPage,logs:logsPage,remediation:remediationPage,reports:reportsPage,settings:settingsPage};view.innerHTML=(renderers[page]||dashboard)();wire()}
function dashboard(){const s=state.stats, max=Math.max(1,...s.severity.map(x=>x.count)), riskAssets=state.riskAssets,activity=s.recentScans;return `${pageHead('Security overview','Your lab network posture at a glance.',btn('Refresh data','refresh',false,false,'↻'))}${state.mode==='demo'?`<div class="demo-banner"><span class="demo-icon">✧</span><div><b>You're exploring a demo environment</b><p>Sample assets, findings and relationships are clearly marked. No demo result came from a live scan.</p></div>${btn('Reset demo','resetDemo',false,true,'↻')}</div>`:''}<section class="kpi-grid"><div class="kpi-card"><div class="kpi-top">Total assets<span class="kpi-icon">▣</span></div><div class="kpi-value">${s.assets}</div><div class="kpi-foot">${state.mode==='demo'?'In demo environment':'In your workspace'}</div></div><div class="kpi-card"><div class="kpi-top">Open services<span class="kpi-icon">⌁</span></div><div class="kpi-value">${s.openPorts}</div><div class="kpi-foot">Across discovered assets</div></div><div class="kpi-card findings"><div class="kpi-top">Active findings<span class="kpi-icon">⚑</span></div><div class="kpi-value">${s.vulnerabilities}</div><div class="kpi-foot">${state.findings.filter(f=>f.status==='open').length} need review</div></div><div class="kpi-card risk"><div class="kpi-top">High risk assets<span class="kpi-icon">△</span></div><div class="kpi-value">${s.highRisk}</div><div class="kpi-foot">Critical or high priority</div></div><div class="kpi-card score"><div class="kpi-top">Average risk score<span class="kpi-icon">◉</span></div><div class="kpi-value">${s.riskScore}<span style="font-size:12px;color:#8795a8"> /100</span></div><div class="kpi-foot">Project-specific heuristic</div></div></section><section class="content-grid"><div class="panel"><div class="panel-head"><div><h2 class="panel-title">Findings by severity</h2><p class="panel-subtitle">Active findings across your assets</p></div><a class="text-link" href="#findings">View findings →</a></div><div class="chart-area"><div class="severity-bars">${s.severity.map(v=>`<div class="bar-group"><span class="bar-value">${v.count}</span><div class="bar-wrap"><i class="bar ${v.name}" style="height:${Math.max(2,v.count/max*100)}%"></i></div><span class="bar-label">${v.name[0].toUpperCase()+v.name.slice(1)}</span></div>`).join('')}</div></div><div class="chart-legend"><span><i class="legend-dot" style="background:#d87681"></i>Critical</span><span><i class="legend-dot" style="background:#e6a05c"></i>High</span><span><i class="legend-dot" style="background:#e4c46c"></i>Medium</span><span><i class="legend-dot" style="background:#65c4a1"></i>Low</span></div></div><div class="panel"><div class="panel-head"><div><h2 class="panel-title">Assets to prioritize</h2><p class="panel-subtitle">Highest calculated risk scores</p></div><a class="text-link" href="#risk">Risk analysis →</a></div><div class="asset-bars">${riskAssets.length?riskAssets.map(a=>`<div class="asset-row"><span class="asset-name">${esc(a.name)}</span><span class="track"><i style="width:${a.riskScore}%"></i></span><span class="score-val">${a.riskScore}</span></div>`).join(''):empty('No assets yet','Add an authorized target to start your assessment.',btn('Add target','addTarget',true,true))}</div></div></section><section class="content-grid"><div class="panel"><div class="panel-head"><div><h2 class="panel-title">Recent activity</h2><p class="panel-subtitle">Latest network assessments</p></div><a class="text-link" href="#scans">Scan history →</a></div><div class="activity-list">${activity.length?activity.map(s=>`<div class="activity-row"><span class="activity-icon">⌁</span><div class="activity-main"><b>${esc(s.targetName)}</b><small>${esc(s.summary||`${s.mode} scan`)} · ${esc(s.status)}</small></div><span class="activity-time">${fmtDate(s.startedAt)}</span></div>`).join(''):empty('No recent scans','Run a lab scan or load the demo environment to see activity.')}</div></div><div class="panel"><div class="panel-head"><div><h2 class="panel-title">Service inventory</h2><p class="panel-subtitle">Most common discovered services</p></div><a class="text-link" href="#assets">All assets →</a></div><div class="asset-bars">${s.services.length?s.services.map(v=>`<div class="asset-row"><span class="asset-name">${esc(v.name)}</span><span class="track"><i style="width:${Math.min(100,v.count/Math.max(...s.services.map(q=>q.count))*100)}%"></i></span><span class="score-val">${v.count}</span></div>`).join(''):empty('No services found','Run a scan to populate service inventory.')}</div></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Quick actions</h2><p class="panel-subtitle">Continue your security assessment</p></div></div><div class="quick-grid"><a class="quick-card" href="#targets"><span class="quick-icon">⊕</span><span><b>Add a target</b><small>Register authorized systems</small></span></a><a class="quick-card" href="#scans"><span class="quick-icon">⌁</span><span><b>Start a scan</b><small>Discover open services</small></span></a><a class="quick-card" href="#findings"><span class="quick-icon">⚑</span><span><b>Review findings</b><small>Prioritize vulnerabilities</small></span></a><a class="quick-card" href="#graph"><span class="quick-icon">⌘</span><span><b>Explore the graph</b><small>Map asset relationships</small></span></a><a class="quick-card" href="#reports"><span class="quick-icon">▤</span><span><b>Export report</b><small>Generate an assessment PDF</small></span></a></div></section>`}
function targets(){const items=state.assets.filter(a=>`${a.name} ${a.ip} ${a.environment}`.toLowerCase().includes(query.toLowerCase()));return `${pageHead('Targets','Manage the systems you own or have explicit permission to assess.',btn('Add target','addTarget',true,false,'＋'))}<div class="note-box" style="margin-bottom:14px">Authorized testing only. Live scans are restricted to loopback, private and link-local IPv4 addresses or local lab hostnames.</div><section class="panel table-panel"><div class="table-tools"><input class="search" id="searchBox" placeholder="Search targets by name or address…" value="${esc(query)}"><span class="spacer"></span><span class="inline-hint">${items.length} targets</span></div>${items.length?`<div class="table-wrap"><table><thead><tr><th>Target</th><th>Address</th><th>Environment</th><th>Criticality</th><th>Assets / ports</th><th>Actions</th></tr></thead><tbody>${items.map(a=>`<tr><td><span class="td-main">${esc(a.name)}</span><span class="td-sub">${esc(a.description||a.type||'Target')}</span></td><td>${esc(a.ip)}</td><td><span class="env-pill" style="background:#1b2938;color:#9fb2c9">${esc(a.environment||'VAPT Lab')}</span></td><td><span class="criticality-pill ${esc(a.criticality)}">${esc(a.criticality)}</span></td><td>${a.ports?.length||0} services</td><td><div class="row-actions"><button class="icon-action" data-action="viewAsset:${a.id}" title="View asset">↗</button><button class="icon-action" data-action="scanTarget:${a.id}" title="Scan target">⌁</button><button class="icon-action" data-action="editAsset:${a.id}" title="Edit target">✎</button><button class="icon-action" data-action="deleteAsset:${a.id}" title="Delete target">×</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No authorized targets','Add a target with an authorization note. The system will reject public addresses for live scans.',btn('Add target','addTarget',true))}</section>`}
function scans(){return `${pageHead('Network scans','Discover hosts, open ports and service versions in your authorized lab.',btn('Start a scan','startScan',true,false,'⌁')+btn('Import Nmap XML','importNmap',false,false,'↑'))}<div class="scan-callout"><span class="scan-callout-icon">⌁</span><div><b>${state.nmapAvailable?'Nmap is available on this machine':'Nmap was not found on this machine'}</b><p>Nmap provides top-100 TCP service discovery; the safe web baseline checks common HTTP response headers. Both require an authorization note and private lab target.</p></div>${btn('Choose scan type','startScan',false,true)}</div><section class="panel table-panel"><div class="table-tools"><b class="panel-title">Scan history</b><span class="spacer"></span><span class="inline-hint">${state.scans.length} assessments</span></div>${state.scans.length?`<div class="table-wrap"><table><thead><tr><th>Target</th><th>Mode</th><th>Status</th><th>Started</th><th>Open ports</th><th>Summary</th></tr></thead><tbody>${state.scans.map(s=>`<tr><td class="td-main">${esc(s.targetName)}</td><td><span class="env-pill" style="color:${s.mode==='demo'?'#90ceea':'#83dcb4'};background:#192630">${esc(s.mode)}</span></td><td><span class="scan-status"><i class="scan-dot ${s.status==='failed'?'failed':''}"></i>${esc(s.status)}</span></td><td>${fmtDate(s.startedAt)}</td><td>${s.portCount??'—'}</td><td style="max-width:270px;white-space:normal">${esc(s.summary||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('No scans yet','Start an authorized lab scan or load the demo environment.')}</section>`}
function assetsPage(){const items=state.riskAssets.filter(a=>`${a.name} ${a.ip} ${a.os}`.toLowerCase().includes(query.toLowerCase()));return `${pageHead('Asset inventory','A structured inventory built from your scans and manually registered assets.',btn('Add asset','addTarget',true,false,'＋'))}<section class="panel table-panel"><div class="table-tools"><input class="search" id="searchBox" placeholder="Search assets…" value="${esc(query)}"><span class="spacer"></span><span class="inline-hint">${items.length} assets</span></div>${items.length?`<div class="table-wrap"><table><thead><tr><th>Asset</th><th>Address</th><th>Operating system</th><th>Services</th><th>Findings</th><th>Risk</th><th>Actions</th></tr></thead><tbody>${items.map(a=>`<tr><td><button class="text-link" style="font-size:11px" data-action="viewAsset:${a.id}">${esc(a.name)}</button><span class="td-sub">${esc(a.type||'asset')}</span></td><td>${esc(a.ip)}</td><td>${esc(a.os||'Unknown')}</td><td>${a.ports?.length||0}<span class="td-sub">${(a.ports||[]).slice(0,3).map(p=>`${p.port}/${p.service}`).join(' · ')||'No scan data'}</span></td><td>${a.findingCount} ${a.findingCount===1?'finding':'findings'}</td><td>${riskPill(a.riskLevel)} <small>${a.riskScore}/100</small></td><td><div class="row-actions"><button class="icon-action" data-action="editAsset:${a.id}" title="Edit">✎</button><button class="icon-action" data-action="scanTarget:${a.id}" title="Scan">⌁</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No assets found','Add a target or run a scan to start your inventory.',btn('Add target','addTarget',true))}</section>`}
function findingsPage(){let items=state.findings.filter(f=>(severityFilter==='all'||f.severity===severityFilter)&&(statusFilter==='all'||f.status===statusFilter)&&(`${f.name} ${asset(f.assetId)?.name||''} ${f.source}`.toLowerCase().includes(query.toLowerCase())));return `${pageHead('Vulnerabilities','Review observed issues as findings. A finding is distinct from a modeled risk path.',btn('Add finding','addFinding',true,false,'＋')+btn('Import ZAP JSON','importZap',false,false,'↑'))}<section class="panel table-panel"><div class="table-tools"><input class="search" id="searchBox" placeholder="Search findings or assets…" value="${esc(query)}"><select class="filter-select" id="severityFilter"><option value="all">All severities</option>${['critical','high','medium','low','info'].map(x=>`<option ${severityFilter===x?'selected':''} value="${x}">${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select><select class="filter-select" id="statusFilter"><option value="all">All statuses</option>${['open','under_review','planned','fixed','retested'].map(x=>`<option ${statusFilter===x?'selected':''} value="${x}">${x.replace('_',' ')}</option>`).join('')}</select><span class="spacer"></span><span class="inline-hint">${items.length} findings</span></div>${items.length?`<div class="table-wrap"><table><thead><tr><th>Finding</th><th>Asset</th><th>Severity</th><th>Source</th><th>CWE / CVE</th><th>Status</th><th>Recommendation</th></tr></thead><tbody>${items.map(f=>`<tr><td><span class="td-main">${esc(f.name)}</span><span class="td-sub">${esc(f.description)}</span></td><td>${esc(asset(f.assetId)?.name||'Unknown')}</td><td>${sevPill(f.severity)}</td><td>${esc(f.source||'Manual review')}</td><td>${f.cwe?esc(f.cwe)+' · ':''}${f.cve?`<a class="text-link" target="_blank" rel="noreferrer" href="https://nvd.nist.gov/vuln/detail/${esc(f.cve)}">${esc(f.cve)}</a>`:'Not Mapped'}</td><td><select class="filter-select status-select" data-finding="${f.id}">${['open','under_review','planned','fixed','retested'].map(x=>`<option value="${x}" ${f.status===x?'selected':''}>${x.replace('_',' ')}</option>`).join('')}</select></td><td style="white-space:normal;min-width:175px">${esc(f.recommendation||'—')}<button class="icon-action" style="margin-left:7px" data-action="simulate:${f.id}" title="Simulate remediation">✳</button></td></tr>`).join('')}</tbody></table></div>`:empty('No findings match your filters','Try changing the filters or add a finding from an assessment.')}</section>`}
function graphPage(){const A=state.assets,R=state.relationships,w=820,h=410,cols=3,positions={};A.forEach((a,i)=>{const col=i%cols,row=Math.floor(i/cols),rows=Math.ceil(A.length/cols);positions[a.id]={x:145+col*265,y:(h/(rows+1))*(row+1)}});const nodes=A.map(a=>{const p=positions[a.id],ra=state.riskAssets.find(x=>x.id===a.id);return `<g class="graph-node ${ra?.riskLevel==='high'||ra?.riskLevel==='critical'?'hot':''}" data-asset="${a.id}" transform="translate(${p.x-83} ${p.y-34})"><rect width="166" height="68"/><circle class="node-dot" cx="14" cy="18" r="4"/><text x="87" y="23">${esc(a.name.length>22?a.name.slice(0,20)+'…':a.name)}</text><text class="node-sub" x="83" y="43">${esc(a.ip)} · ${(a.ports||[]).length} services</text></g>`}).join('');const edges=R.map(r=>{const a=positions[r.source],b=positions[r.target];if(!a||!b)return '';const ra=state.riskAssets.find(x=>x.id===r.source),hot=ra?.findingCount>0&&state.riskAssets.find(x=>x.id===r.target)?.criticality==='critical';return `<g><line class="graph-edge ${hot?'hot':''}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/><text class="graph-edge-label" x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2-5}">${esc(r.type)}</text></g>`}).join('');return `${pageHead('Security graph','Explore how assets connect. Select a node for details or create relationships between systems.',btn('Add relationship','addRelationship',true,false,'＋'))}<section class="panel" style="margin-bottom:14px"><div class="panel-head"><div><h2 class="panel-title">Network relationship map</h2><p class="panel-subtitle">${A.length} assets · ${R.length} relationships · Data from this workspace</p></div><div class="graph-legend"><span><i class="graph-dot"></i>Asset</span><span><i class="graph-dot hot"></i>Finding connected to critical asset</span></div></div>${A.length?`<div class="graph-wrap"><svg viewBox="0 0 ${w} ${Math.max(h,Math.ceil(A.length/3)*180)}" role="img" aria-label="Network asset relationship graph">${edges}${nodes}</svg></div>`:empty('No assets to map','Add targets to populate the security graph.',btn('Add target','addTarget',true))}</section><div class="two-col"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Relationships</h2><p class="panel-subtitle">Modeled asset dependencies</p></div></div>${R.length?`<div class="activity-list">${R.map(r=>`<div class="activity-row"><div class="activity-main"><b>${esc(asset(r.source)?.name||'Unknown')} <span style="color:#e0a274">→</span> ${esc(asset(r.target)?.name||'Unknown')}</b><small>${esc(r.type)}</small></div><button class="icon-action" data-action="deleteRel:${r.id}" title="Remove relationship">×</button></div>`).join('')}</div>`:empty('No relationships yet','Add connections to create a useful network map.')}</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Graph interpretation</h2><p class="panel-subtitle">What the highlighted links mean</p></div></div><p class="inline-hint" style="line-height:1.8">The graph displays modeled access and dependency relationships. Highlighted edges indicate a source asset with active findings connected to a critical asset. A relationship is context for review and does not demonstrate exploitability.</p></section></div>`}
function riskPage(){const s=state.stats, assets=state.riskAssets,paths=[];for(const r of state.relationships){const src=asset(r.source),dst=asset(r.target),ra=assets.find(x=>x.id===r.source),findings=state.findings.filter(f=>f.assetId===r.source&&f.status!=='fixed');if(src&&dst&&findings.length)paths.push({src,dst,relationship:r,findings,critical:dst.criticality==='critical'})}const reasons=assets.length?assets.slice().sort((a,b)=>b.riskScore-a.riskScore)[0]:null;return `${pageHead('Risk analysis','Transparent asset scoring and explainable relationship-based risk scenarios.') }<div class="risk-summary"><section class="panel score-card"><div class="score-ring" style="--score-pct:${s.riskScore}%;--score-color:${s.riskScore>=65?'#e8797c':s.riskScore>=40?'#e3a264':'#57d1ab'}"><span>${s.riskScore}</span></div><div class="score-copy"><b>Overall workspace risk</b><p>${s.riskLevel.toUpperCase()} · Average asset score<br>CampusShield project-specific heuristic, not CVSS.</p></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Why the top asset is prioritized</h2><p class="panel-subtitle">${reasons?esc(reasons.name):'No assets available'}</p></div>${reasons?riskPill(reasons.riskLevel):''}</div>${reasons?`<div class="reason-list"><div class="reason"><i>✓</i>${reasons.findingCount} active finding${reasons.findingCount===1?'':'s'} contribute to its score.</div><div class="reason"><i>✓</i>${(reasons.ports||[]).length} exposed service${(reasons.ports||[]).length===1?'':'s'} add exposure points.</div><div class="reason"><i>✓</i>${reasons.relationshipCount} modeled relationship${reasons.relationshipCount===1?'':'s'} contribute context.</div><div class="reason"><i>✓</i>${esc(reasons.criticality)} asset criticality adds ${({low:0,medium:4,high:8,critical:12})[reasons.criticality]||0} points.</div>${reasons.connectedCritical?'<div class="reason"><i>✓</i>Finding-bearing asset is linked to a critical database (+10).</div>':''}</div>`:empty('No scoring data','Add assets and findings.')}</section></div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Potential risk paths</h2><p class="panel-subtitle">Finding-bearing assets and their downstream connections</p></div><span class="inline-hint">${paths.length} scenarios</span></div>${paths.length?`<div class="path-list">${paths.map(p=>`<div class="path-card"><div class="path-title"><span class="td-main">${p.critical?'Critical dependency':'Relationship for review'}</span>${p.critical?riskPill('high'):'<span class="criticality-pill">Context</span>'}</div><div class="path-nodes"><span class="path-node">${esc(p.src.name)} · ${p.findings.length} finding${p.findings.length===1?'':'s'}</span><span class="path-arrow">— ${esc(p.relationship.type)} →</span><span class="path-node">${esc(p.dst.name)} · ${esc(p.dst.criticality)}</span></div><p class="path-explanation">${esc(p.src.name)} has ${p.findings.map(f=>f.name).join(', ')} and a modeled ${esc(p.relationship.type.toLowerCase())} relationship with ${esc(p.dst.name)}. Review whether this access is required and appropriately restricted. This is a prioritization scenario, not proof of an attack path.</p></div>`).join('')}</div>`:empty('No relationship risk scenarios','Add a finding and connect its asset to another system to see explainable risk scenarios.')}</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Asset risk ranking</h2><p class="panel-subtitle">Transparent heuristic: findings + exposure + relationships + criticality</p></div></div><div class="asset-bars">${assets.slice().sort((a,b)=>b.riskScore-a.riskScore).map(a=>`<div class="asset-row" style="grid-template-columns:minmax(90px,1.2fr) 1fr 30px"><span class="asset-name">${esc(a.name)}</span><span class="track"><i style="width:${a.riskScore}%"></i></span><span class="score-val">${a.riskScore}</span></div><div style="margin:-7px 0 2px 2px;font-size:9px;color:#8290a2">${esc(a.criticality)} criticality · ${a.findingCount} findings · ${a.relationshipCount} links</div>`).join('')||empty('No assets','Add an authorized target.')}</div></section></div>`}
function packetsPage(){return `${pageHead('Packet analysis','Offline summaries of authorized classic PCAP captures. No live traffic is collected.') }<div class="two-col"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Analyze a capture file</h2><p class="panel-subtitle">Classic PCAP · Ethernet link type · PCAPNG not supported yet</p></div></div><label class="upload-zone" id="pcapDrop"><span class="upload-symbol">⇧</span><b>Choose or drop a .pcap file</b><p>Offline analysis only. Files are processed locally and the summary is retained in your workspace.</p><input type="file" id="pcapFile" accept=".pcap,application/vnd.tcpdump.pcap,application/octet-stream"><button type="button" class="btn btn-primary btn-sm" data-action="choosePcap">Select PCAP</button><div id="pcapStatus" class="inline-hint" style="margin-top:8px"></div></label></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Protocol summary</h2><p class="panel-subtitle">${state.packets[0]?`${esc(state.packets[0].filename)} · ${state.packets[0].packetCount} packets`:'No capture analyzed yet'}</p></div></div>${state.packets[0]?.protocols?.length?`<div class="result-list">${state.packets[0].protocols.map(x=>`<div class="result-item"><span class="result-name">${esc(x.name)} ${x.risk==='review'?'<small>· Review unencrypted protocol</small>':''}</span><span class="result-count">${x.packets}</span>${x.risk==='review'?riskPill('medium'):'<span class="criticality-pill">Normal</span>'}</div>`).join('')}</div><p class="inline-hint" style="margin-top:10px">Flows are aggregated by source, destination, ports and transport protocol. Packet contents are not inspected.</p>`:empty('Upload a PCAP capture','Protocol and flow summaries will appear here.')}</section></div>${state.packets[0]?.flows?.length?`<section class="panel table-panel" style="margin-top:14px"><div class="table-tools"><b class="panel-title">Top conversations</b><span class="spacer"></span><span class="inline-hint">${state.packets[0].flows.length} flows</span></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Destination</th><th>Protocol</th><th>Source port</th><th>Destination port</th><th>Packets</th></tr></thead><tbody>${state.packets[0].flows.slice(0,30).map(f=>`<tr><td>${esc(f.source)}</td><td>${esc(f.destination)}</td><td>${esc(f.protocol)}</td><td>${f.sourcePort}</td><td>${f.destinationPort}</td><td>${f.packets}</td></tr>`).join('')}</tbody></table></div></section>`:''}`}
function logsPage(){const current=state.logs[0];return `${pageHead('Log analysis','Look for repeated failed logins and basic HTTP error patterns in authorized logs.') }<div class="two-col"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Analyze a log file</h2><p class="panel-subtitle">Plain-text logs · Processed offline, locally</p></div></div><label class="upload-zone" id="logDrop"><span class="upload-symbol">≡</span><b>Choose or drop a .log or .txt file</b><p>Maximum 1 MB. Analysis aggregates repeated login failures and HTTP errors without sending log data elsewhere.</p><input type="file" id="logFile" accept=".log,.txt,text/plain"><button type="button" class="btn btn-primary btn-sm" data-action="chooseLog">Select log file</button><div id="logStatus" class="inline-hint" style="margin-top:8px"></div></label></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Analysis summary</h2><p class="panel-subtitle">${current?`${esc(current.filename)} · ${current.lineCount} lines`:'No logs analyzed yet'}</p></div></div>${current?`<div class="result-list">${current.findings.map(f=>`<div class="result-item"><span class="result-name"><b>${esc(f.event)}</b><small> · ${esc(f.ip)}</small></span><span class="result-count">${f.count}</span>${riskPill(f.risk==='high'?'high':f.risk==='medium'?'medium':'low')}</div>`).join('')||'<p class="inline-hint">No event patterns were recognized.</p>'}</div><p class="inline-hint" style="margin-top:10px">Heuristic summary only; this is not an intrusion detection system.</p>`:empty('Upload an authorized log','Repeated event summaries will appear here.')}</section></div>${current?.findings?.length?`<section class="panel table-panel" style="margin-top:14px"><div class="table-tools"><b class="panel-title">Event groups</b></div><div class="table-wrap"><table><thead><tr><th>Source IP</th><th>Event</th><th>Count</th><th>Risk</th><th>Example evidence</th></tr></thead><tbody>${current.findings.map(f=>`<tr><td>${esc(f.ip)}</td><td>${esc(f.event)}</td><td>${f.count}</td><td>${riskPill(f.risk==='high'?'high':f.risk==='medium'?'medium':'low')}</td><td style="white-space:normal;min-width:240px">${esc(f.samples?.[0]||'—')}</td></tr>`).join('')}</tbody></table></div></section>`:''}`}
function remediationPage(){const active=state.simulations.filter(x=>x.active);return `${pageHead('Remediation','Track finding status and model the effect of a proposed fix.',active.length?btn('Undo latest simulation','undoSimulation',false,false,'↶'):'')}${active.length?`<div class="demo-banner" style="border-color:#315b4d;background:#14241f"><span class="demo-icon" style="color:#86ddb9">✳</span><div><b>What-if simulation active</b><p>${active.length} simulated fix${active.length===1?'':'es'} affect the risk view. No target or finding status has been changed.</p></div>${btn('Undo all simulations','undoAll',false,true,'↶')}</div>`:''}<div class="stepper"><span class="step complete"><i>1</i>Open</span><span class="step ${state.findings.some(f=>f.status==='under_review')?'complete':''}"><i>2</i>Under review</span><span class="step ${state.findings.some(f=>f.status==='planned')?'complete':''}"><i>3</i>Planned</span><span class="step ${state.findings.some(f=>f.status==='fixed')?'complete':''}"><i>4</i>Fixed</span><span class="step ${state.findings.some(f=>f.status==='retested')?'complete':''}"><i>5</i>Retested</span></div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Recommended actions</h2><p class="panel-subtitle">Recommendations attached to active findings</p></div></div>${state.findings.filter(f=>f.status!=='fixed').length?`<div class="activity-list">${state.findings.filter(f=>f.status!=='fixed').map(f=>`<div class="activity-row"><div class="activity-main"><b>${esc(f.name)} · ${esc(asset(f.assetId)?.name||'Unknown')}</b><small>${esc(f.recommendation||'Review and retest after fixing.')}</small></div>${sevPill(f.severity)}<button class="btn btn-sm" data-action="simulate:${f.id}">Simulate fix</button></div>`).join('')}</div>`:empty('All findings are marked fixed','Add or reopen a finding to track remediation.')}</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Simulation comparison</h2><p class="panel-subtitle">Workspace risk score before and after a fix</p></div></div>${state.simulations.length?state.simulations.map(sim=>`<div class="recommendation"><div style="display:flex;align-items:center;justify-content:space-between"><b>${esc(sim.findingName)}</b><span class="criticality-pill">${sim.active?'Active scenario':'Undone'}</span></div><p>Average risk score: <strong>${sim.before}</strong> → <strong>${sim.after}</strong> <span style="color:${sim.after<sim.before?'#7be0b8':'#e3bb73'}">(${sim.after<sim.before?'−':''}${Math.abs(sim.before-sim.after)} points)</span></p></div>`).join(''):empty('No simulations yet','Choose a finding and simulate a fix to compare its calculated risk.')}</section></div><div class="note-box" style="margin-top:14px">Simulation is a what-if model only. It does not change a target, close a port, remove a finding, or claim a successful retest. Use the finding status workflow after verifying a real remediation.</div>`}
function reportsPage(){const s=state.stats;return `${pageHead('Reports','Generate an assessment summary using the data currently stored in this workspace.',btn('Download PDF','downloadReport',true,false,'↓'))}<section class="report-cover"><div class="eyebrow">ASSESSMENT EXPORT</div><h2>CampusShield Security Assessment</h2><p>A local summary of assessment scope, assets, services, findings, relationships, risk reasoning and remediation guidance.</p><div class="report-metrics"><div><b>${s.assets}</b><small>Assets</small></div><div><b>${s.openPorts}</b><small>Services</small></div><div><b>${s.vulnerabilities}</b><small>Active findings</small></div><div><b>${s.riskScore}<span style="font-size:10px;color:#94a4b5"> /100</span></b><small>Workspace risk</small></div></div></section><div class="two-col" style="margin-top:14px"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Included sections</h2><p class="panel-subtitle">Report contents are built from this workspace</p></div></div><div class="asset-bars">${['Assessment scope & authorization note','Target and asset inventory','Open port and service summary','Vulnerability findings and status','Relationships and modeled risk context','Project-specific risk summary','Remediation recommendations','PCAP and log analysis limitations'].map(x=>`<div class="reason"><i>✓</i>${x}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Report provenance</h2><p class="panel-subtitle">Scope and interpretation</p></div></div><div class="settings-row"><span>Workspace mode</span><b>${state.mode==='demo'?'Demo data':'Live lab data'}</b></div><div class="settings-row"><span>Generated</span><b>${new Date().toLocaleDateString()}</b></div><div class="settings-row"><span>Authorization</span><b>Authorized assessment only</b></div><div class="note-box" style="margin-top:10px">${state.mode==='demo'?'DEMO DATA — NOT FROM A LIVE SCAN.':'Report contains locally recorded assessment data.'} Risk is an educational heuristic, not CVSS.</div></section></div>`}
function settingsPage(){return `${pageHead('Settings','Workspace mode, data handling and assessment guardrails.') }<div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Environment mode</h2><p class="panel-subtitle">Choose whether the workspace is showing sample or lab data</p></div></div><div class="radio-row"><label class="radio-card"><input type="radio" name="mode" value="demo" ${state.mode==='demo'?'checked':''}><span><b>Demo mode</b><br><small>Sample lab environment</small></span></label><label class="radio-card"><input type="radio" name="mode" value="live" ${state.mode==='live'?'checked':''}><span><b>Live lab mode</b><br><small>Your registered assets</small></span></label></div><p class="inline-hint" style="margin:12px 0 0">The top-bar button switches modes. Each direction asks before replacing the current mode\u2019s dataset.</p></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Safety & data</h2><p class="panel-subtitle">How CampusShield handles assessments</p></div></div><div class="settings-row"><span>Server binding<small>Loopback only (127.0.0.1)</small></span><span class="criticality-pill low">LOCAL</span></div><div class="settings-row"><span>Live scan scope<small>Loopback, private and link-local IPv4</small></span><span class="criticality-pill low">LIMITED</span></div><div class="settings-row"><span>Scan engine<small>${state.nmapAvailable?'Nmap detected':'Nmap not detected'}</small></span><span class="criticality-pill">${state.nmapAvailable?'READY':'OPTIONAL'}</span></div><div class="settings-row"><span>Persistence<small>Local JSON workspace file</small></span><span class="criticality-pill">LOCAL</span></div><div class="note-box">Authorized testing only. Add an explicit authorization note to each live-scan target. PCAP and log uploads are processed locally.</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Risk model</h2><p class="panel-subtitle">Inspectable scoring components</p></div></div><p class="inline-hint" style="line-height:1.8">Severity-weighted active findings (critical 24, high 15, medium 8, low 3) + up to 12 exposure points + up to 10 relationship points + asset criticality (0–12) + 10 points when an asset with findings is connected to a critical asset. Asset scores are capped at 100; workspace score is the rounded average.</p><span class="criticality-pill">NOT CVSS</span></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Demo environment</h2><p class="panel-subtitle">Restore the bundled example network</p></div></div><p class="inline-hint">Creates five sample assets, example findings, relationships and a demonstration scan history. This replaces current workspace data.</p>${btn('Reset to demo data','resetDemo',false,false,'↻')}</section></div>`}
function wire(){
 $$('[data-action]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action)));
 const sb=$('#searchBox');if(sb)sb.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;const top=window.scrollY;render();const el=$('#searchBox');el?.focus();el?.setSelectionRange(pos,pos);window.scrollTo(0,top)});
 $('#severityFilter')?.addEventListener('change',e=>{severityFilter=e.target.value;render()});$('#statusFilter')?.addEventListener('change',e=>{statusFilter=e.target.value;render()});
 $$('.status-select').forEach(s=>s.addEventListener('change',async()=>{try{await patch(`/api/findings/${s.dataset.finding}`,{status:s.value});await refresh();toast('Finding status updated.')}catch(e){toast(e.message,true)}}));
 $$('[name="mode"]').forEach(x=>x.addEventListener('change',async()=>{try{if(x.value==='live'&&state.mode==='demo'&&!confirm('Switching to Live removes the bundled demo assets, findings, relationships and scan history. Continue?')){render();return}if(x.value==='demo'&&state.mode==='live'&&!confirm('Switching to Demo replaces all live workspace data with bundled demo fixtures. Continue?')){render();return}await post('/api/mode',{mode:x.value,clearDemo:x.value==='live',clearLive:x.value==='demo'});await refresh();toast(`Workspace label changed to ${x.value} mode.`)}catch(e){toast(e.message,true)}}));
 $$('.graph-node').forEach(n=>n.addEventListener('click',()=>assetModal(n.dataset.asset)));
 setupDrop('pcapDrop','pcapFile','pcapStatus',analyzePcap);setupDrop('logDrop','logFile','logStatus',analyzeLog);
}
function setupDrop(zoneId,inputId,statusId,fn){const z=$('#'+zoneId),i=$('#'+inputId);if(!z||!i)return;i.onchange=()=>i.files?.[0]&&fn(i.files[0]);z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('drag')});z.addEventListener('dragleave',()=>z.classList.remove('drag'));z.addEventListener('drop',e=>{e.preventDefault();z.classList.remove('drag');if(e.dataTransfer.files[0])fn(e.dataTransfer.files[0])})}
function openModal(title,sub,fields,onSubmit,submit='Save'){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" id="backdrop"><section class="modal" role="dialog" aria-modal="true"><header class="modal-head"><div><h2>${title}</h2><p>${sub}</p></div><button class="icon-btn" data-action="closeModal" aria-label="Close">×</button></header><form id="modalForm" class="modal-body"><div class="form-grid">${fields}</div><div class="modal-actions"><button type="button" class="btn" data-action="closeModal">Cancel</button><button type="submit" class="btn btn-primary">${submit}</button></div></form></section></div>`;$('#backdrop').addEventListener('click',e=>{if(e.target.id==='backdrop')closeModal()});$('#modalForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target),d=Object.fromEntries(fd.entries()),submit=e.target.querySelector('button[type="submit"]');submit.disabled=true;submit.textContent=submit.textContent==='Run scan'?'Scanning…':'Saving…';try{await onSubmit(d);closeModal();await refresh()}catch(err){submit.disabled=false;submit.textContent=submit.textContent==='Scanning…'?'Run scan':'Save';toast(err.message,true)}});wire()}
const field=(name,label,type='text',value='',opts=null,required=false,full=false,placeholder='')=>`<div class="field ${full?'full':''}"><label>${label}</label>${opts?`<select class="field-select" name="${name}">${opts.map(x=>`<option value="${esc(x[0])}" ${value===x[0]?'selected':''}>${esc(x[1])}</option>`).join('')}</select>`:type==='textarea'?`<textarea class="field-textarea" name="${name}" ${required?'required':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input class="field-input" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} placeholder="${esc(placeholder)}">`}</div>`;
async function targetModal(a){const edit=!!a;if(!edit&&state.mode==='demo'){if(!confirm('Switch to Live Lab Mode? This removes the bundled demo fixtures before you add authorized targets.'))return;try{await post('/api/mode',{mode:'live',clearDemo:true});await refresh()}catch(e){toast(e.message,true);return}}openModal(edit?'Edit asset':'Add authorized target',edit?'Update the local asset inventory.':'Record scope and authorization before adding a scan target.',`${field('name','Target name',null,a?.name||'',null,true)}${field('ip','IP address / hostname',null,a?.ip||'',null,true)}${field('environment','Environment',null,a?.environment||'VAPT Lab',null,false)}${field('criticality','Asset criticality',null,a?.criticality||'medium',[['low','Low'],['medium','Medium'],['high','High'],['critical','Critical']])}${field('type','Asset type',null,a?.type||'server',[['endpoint','Endpoint'],['application','Application'],['server','Server'],['database','Database'],['network','Network device']])}${field('description','Description','textarea',a?.description||'',null,false,true)}${!edit?field('authorization','Authorization note','textarea','',null,true,true,'e.g. Owned DVWA VM, approved for assessment by lab supervisor'):''}`,async d=>{if(edit)await patch(`/api/assets/${a.id}`,d);else await post('/api/targets',d)},edit?'Save changes':'Add target')}
function addFindingModal(){if(!state.assets.length)return toast('Add an asset before recording a finding.',true);openModal('Record finding','Enter an observed or manually reviewed security finding.',`${field('assetId','Affected asset',null,state.assets[0].id,state.assets.map(a=>[a.id,a.name]),true)}${field('severity','Severity',null,'medium',['critical','high','medium','low','info'].map(x=>[x,x[0].toUpperCase()+x.slice(1)]))}${field('name','Finding name',null,'',null,true,true)}${field('source','Detection source',null,'Manual review')}${field('cve','Verified CVE <small>(optional)</small>',null,'',null,false,false,'CVE-2024-12345')}${field('description','Description','textarea','',null,false,true)}${field('evidence','Evidence','textarea','',null,false,true)}${field('recommendation','Recommendation','textarea','',null,false,true)}`,d=>post('/api/findings',d),'Add finding')}
function relationshipModal(){if(state.assets.length<2)return toast('Add at least two assets before creating a relationship.',true);openModal('Create relationship','Model an access path or dependency between two assets.',`${field('source','From asset',null,state.assets[0].id,state.assets.map(a=>[a.id,a.name]),true)}${field('target','To asset',null,state.assets[1].id,state.assets.map(a=>[a.id,a.name]),true)}${field('type','Relationship type',null,'Network Access',['Network Access','Application Access','Database Connection','Administrative Access','Authentication Dependency','Shared Service'].map(x=>[x,x]),true,true)}`,d=>post('/api/relationships',d),'Add relationship')}
function scanModal(){const targets=state.assets.filter(a=>a.authorization?.trim());if(!targets.length)return toast('Register an authorized private lab target first.',true);openModal('Start authorized lab scan','Nmap service detection · Top 100 TCP ports · private/loopback scope',`${field('targetId','Target',null,targets[0].id,targets.map(a=>[a.id,`${a.name} · ${a.ip}`]),true,true)}${field('scanType','Assessment type',null,'nmap',[['nmap','Nmap service and port discovery'],['web','Safe read-only web baseline']])}<div class="field full"><div class="note-box">${'Nmap requires Nmap on this computer; Safe web baseline sends bounded GET requests to discovered HTTP services.'} Confirm you have explicit authorization to test the selected asset.</div></div>`,async d=>{try{const r=await post('/api/scans',d);toast(`${r.scan.status==='completed'?'Scan completed':'Scan failed'}: ${r.scan.summary}`,r.scan.status!=='completed')}catch(e){await refresh();throw e}},'Run scan')}
function assetModal(aid){const a=asset(aid),r=state.riskAssets.find(x=>x.id===aid);if(!a)return;$('#modalRoot').innerHTML=`<div class="modal-backdrop" id="backdrop"><section class="modal"><header class="modal-head"><div><h2>${esc(a.name)}</h2><p>${esc(a.ip)} · ${esc(a.environment||'VAPT Lab')}</p></div><button class="icon-btn" data-action="closeModal">×</button></header><div class="modal-body"><div class="asset-detail-grid"><div class="detail-tile"><small>Operating system</small><b>${esc(a.os||'Unknown')}</b></div><div class="detail-tile"><small>Criticality · Risk</small><b>${esc(a.criticality)} · ${r?.riskScore??0}/100</b></div><div class="detail-tile"><small>Open services</small><b>${(a.ports||[]).length}</b></div><div class="detail-tile"><small>Active findings</small><b>${r?.findingCount??0}</b></div></div><h3 class="panel-title" style="margin:15px 0 8px">Services</h3>${a.ports?.length?`<div class="asset-bars">${a.ports.map(p=>`<div class="activity-row"><span class="activity-main"><b>${p.port}/${esc(p.protocol)}</b><small>${esc(p.service)} ${esc(p.version)}</small></span></div>`).join('')}</div>`:'<p class="inline-hint">No scan results recorded.</p>'}<h3 class="panel-title" style="margin:15px 0 8px">Findings</h3>${state.findings.filter(f=>f.assetId===aid).map(f=>`<div class="recommendation"><b>${esc(f.name)} ${sevPill(f.severity)}</b><p>${esc(f.recommendation)}</p></div>`).join('')||'<p class="inline-hint">No findings recorded.</p>'}<div class="modal-actions"><button class="btn" data-action="closeModal">Close</button><button class="btn btn-primary" data-action="editAsset:${aid}">Edit asset</button></div></div></section></div>`;wire();$('#backdrop').onclick=e=>{if(e.target.id==='backdrop')closeModal()}}
function closeModal(){$('#modalRoot').innerHTML=''}
async function analyzePcap(file){const s=$('#pcapStatus');if(file.size>8*1024*1024)return toast('PCAP must be under 8 MB.',true);s.textContent='Reading and analyzing capture…';try{const b=await file.arrayBuffer();const bytes=new Uint8Array(b);let binary='';for(let n=0;n<bytes.length;n+=32768)binary+=String.fromCharCode(...bytes.subarray(n,n+32768));const content=btoa(binary);await post('/api/analyze-pcap',{filename:file.name,content});await refresh();toast('PCAP summary created.')}catch(e){s.textContent=e.message;toast(e.message,true)}}
async function analyzeLog(file){const s=$('#logStatus');if(file.size>1_000_000)return toast('Log file must be under 1 MB.',true);s.textContent='Reading and analyzing log…';try{const content=await file.text();await post('/api/analyze-log',{filename:file.name,content});await refresh();toast('Log summary created.')}catch(e){s.textContent=e.message;toast(e.message,true)}}
async function act(a){if(a==='closeModal')return closeModal();if(a==='refresh')return refresh().then(()=>toast('Workspace data refreshed.'));if(a==='addTarget')return targetModal();if(a==='addFinding')return addFindingModal();if(a==='addRelationship')return relationshipModal();if(a==='startScan')return scanModal();if(a==='toggleMode')return switchMode(state.mode==='demo'?'live':'demo');if(a==='importNmap')return importReport('nmap');if(a==='importZap')return importReport('zap');if(a==='resetDemo'){if(!confirm('Reset the workspace to the bundled demonstration environment? This replaces the current local data.'))return;try{await post('/api/reset-demo',{});query='';await refresh();toast('Demo environment restored.')}catch(e){toast(e.message,true)}return}if(a==='undoSimulation'){const sim=state.simulations.find(x=>x.active);if(sim)await undo(sim);return}if(a==='undoAll'){for(const s of state.simulations.filter(x=>x.active))await undo(s,false);await refresh();toast('All what-if simulations have been undone.');return}if(a==='downloadReport'){window.location.href='/api/report.pdf';return}if(a==='choosePcap')return $('#pcapFile')?.click();if(a==='chooseLog')return $('#logFile')?.click();if(a.startsWith('viewAsset:'))return assetModal(a.split(':')[1]);if(a.startsWith('editAsset:')){const x=asset(a.split(':')[1]);if(x){closeModal();targetModal(x)}return}if(a.startsWith('scanTarget:')){const tid=a.split(':')[1];scanModal();const sel=$('[name="targetId"]');if(sel)sel.value=tid;return}if(a.startsWith('deleteAsset:')){const aid=a.split(':')[1];const x=asset(aid);if(!confirm(`Delete ${x?.name||'this asset'} and its linked findings and relationships?`))return;try{await del(`/api/assets/${aid}`);await refresh();toast('Asset and linked records deleted.')}catch(e){toast(e.message,true)}return}if(a.startsWith('deleteRel:')){try{await del(`/api/relationships/${a.split(':')[1]}`);await refresh();toast('Relationship removed.')}catch(e){toast(e.message,true)}return}if(a.startsWith('simulate:')){const f=state.findings.find(x=>x.id===a.split(':')[1]);if(!f)return;try{const s=await post('/api/simulations',{findingId:f.id});await refresh();toast(`What-if complete: workspace score ${s.before} → ${s.after}.`)}catch(e){toast(e.message,true)}}}
async function undo(s,notify=true){try{await post('/api/simulations/undo',{id:s.id});await refresh();if(notify)toast('What-if simulation undone.')}catch(e){toast(e.message,true)}}
async function refresh(){try{state=await api('/api/state');render()}catch(e){toast(e.message,true)}}
document.addEventListener('click',e=>{const l=e.target.closest('a[data-page]');if(l){e.preventDefault();query='';setPage(l.dataset.page)}else if(e.target.closest('.quick-card')){e.preventDefault();setPage(e.target.closest('.quick-card').getAttribute('href').slice(1))}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(labelMap[p]){page=p;render()}});
$('#menuButton').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
document.addEventListener('click',e=>{if(innerWidth<=760&&$('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menuButton'))$('#sidebar').classList.remove('open')});
refresh();
function importReport(kind){const targets=state.assets.filter(a=>a.authorization?.trim());if(!targets.length)return toast('Register a target with an authorization note before importing scanner results.',true);const zap=kind==='zap',accept=zap?'.json,application/json':'.xml,text/xml,application/xml';openModal(zap?'Import OWASP ZAP JSON':'Import Nmap XML',zap?'Import alerts for the selected authorized asset. Out-of-scope hosts are skipped.':'Import an Nmap host report. The report IPv4 address must match the selected target.',`${field('targetId','Authorized asset',null,targets[0].id,targets.map(a=>[a.id,`${a.name} · ${a.ip}`]),true,true)}<div class="field full"><label>Scanner report</label><input id="importFile" class="field-input" type="file" accept="${accept}" required></div>`,async d=>{const file=$('#importFile')?.files?.[0];if(!file)throw new Error('Choose a report file.');if(file.size>(zap?4:7.5)*1024*1024)throw new Error('Report is too large.');const result=await post(zap?'/api/import/zap-json':'/api/import/nmap-xml',{targetId:d.targetId,content:await file.text()});toast(result.scan.summary)},'Import report')}
async function switchMode(target){if(!state||target===state.mode)return;const message=target==='live'?'Switch to Live Lab Mode? This removes the bundled demo assets, findings, relationships and scan history.':'Switch to Demo Mode? This replaces the current live workspace data with the bundled sample environment.';if(!confirm(message))return;try{await post('/api/mode',{mode:target,clearDemo:target==='live',clearLive:target==='demo'});query='';await refresh();toast(`Switched to ${target==='demo'?'Demo':'Live Lab'} Mode.`)}catch(e){toast(e.message,true)}}
